  const [gx, gy] = def.goal;
  if (grid[gy] && grid[gy][gx] === ' ') grid[gy][gx] = 'G';
  const [sx, sy] = def.spawn;
  if (grid[sy] && grid[sy][sx] === ' ') grid[sy][sx] = 'S';

