    ...def,
    cols: w, rows: h,
    pxW: w * TILE_UNIT, pxH: h * TILE_UNIT,
    grid,
    goalPx: { x: gx * TILE_UNIT + TILE_UNIT / 2, y: gy * TILE_UNIT + TILE_UNIT / 2 },
