for (const def of LEVELS) {
  if (only && def.id !== only) continue;
  const t0 = Date.now();
  const res = solve(def);
  const ms = Date.now() - t0;
  if (res.ok) {
    console.log(`✓ ${String(def.id).padStart(2, '0')} ${def.name.padEnd(16)} ${(res.frames / 60).toFixed(1)}s   ${res.expanded} nodes   ${ms}ms`);
