1: // Shared, deterministic player physics. Used by the game loop AND the offline
2: // level validator so "solvable" means the exact same thing in both places.
3: //
4: // Units are pixels and frames (fixed 60 Hz). Gravity is +y unless flipped.
5: 
6: export const TILE = 34;
7: export const PW = 18;
8: export const PH = 24;
9: 
10: export const K = {
11:   gravity: 0.62,
12:   accel: 0.86,
13:   maxRun: 4.4,
14:   frictionGround: 0.76,
15:   frictionAir: 0.94,
16:   jump: 11.6,
17:   maxFall: 14,
18:   coyoteFrames: 7,
19:   bufferFrames: 7,
20:   jumpCut: 0.48,
21: };
