29: export function tileAt(level, tx, ty) {
30:   if (tx < 0 || ty < 0 || tx >= level.cols || ty >= level.rows) return '#';
31:   return level.grid[ty][tx];
32: }
33: 
34: export function isSolidChar(ch, phase) {
35:   if (ch === '#') return true;
36:   if (ch === 'A') return phase === 0;
37:   if (ch === 'B') return phase === 1;
38:   if (ch === 'c' || ch === '~') return true;
39:   return false;
40: }
41: 
42: export function isSolid(level, tx, ty, phase, dynamic) {
43:   const ch = tileAt(level, tx, ty);
44:   if (dynamic) {
45:     const override = dynamic(tx, ty, ch, phase);
46:     if (override !== undefined && override !== null) return override;
47:   }
48:   return isSolidChar(ch, phase);
49: }
