51: // Is any solid tile overlapping this AABB?
52: export function boxSolid(level, x, y, w, h, phase, dynamic) {
53:   const x0 = Math.floor(x / TILE), x1 = Math.floor((x + w - 0.01) / TILE);
54:   const y0 = Math.floor(y / TILE), y1 = Math.floor((y + h - 0.01) / TILE);
55:   for (let ty = y0; ty <= y1; ty++) {
56:     for (let tx = x0; tx <= x1; tx++) {
57:       if (isSolid(level, tx, ty, phase, dynamic)) return true;
58:     }
59:   }
60:   return false;
61: }
