63: export function makePlayer(spawn, phase = 0) {
64:   return {
65:     x: spawn.x * TILE + (TILE - PW) / 2,
66:     y: spawn.y * TILE + (TILE - PH) / 2,
67:     w: PW, h: PH,
68:     vx: 0, vy: 0,
69:     grounded: false,
70:     coyote: 0,
71:     buffer: 0,
72:     cut: false,
73:     phase,
74:     gravDir: 1,
75:     facing: 1,
76:     alive: true,
77:   };
78: }
