80: function resolveX(level, p, phase, dynamic) {
81:   const x0 = Math.floor(p.x / TILE);
82:   const x1 = Math.floor((p.x + p.w - 0.01) / TILE);
83:   const y0 = Math.floor(p.y / TILE);
84:   const y1 = Math.floor((p.y + p.h - 0.01) / TILE);
85:   let hit = false;
86:   for (let ty = y0; ty <= y1; ty++) {
87:     for (let tx = x0; tx <= x1; tx++) {
88:       if (!isSolid(level, tx, ty, phase, dynamic)) continue;
89:       const left = tx * TILE, right = left + TILE;
90:       if (p.vx > 0) p.x = left - p.w - 0.01;
91:       else if (p.vx < 0) p.x = right + 0.01;
92:       else p.x = left - p.w - 0.01;
93:       p.vx = 0;
94:       hit = true;
95:     }
96:     if (hit) break;
97:   }
98: }
