100: function resolveY(level, p, phase, dynamic) {
101:   const x0 = Math.floor(p.x / TILE);
102:   const x1 = Math.floor((p.x + p.w - 0.01) / TILE);
103:   const y0 = Math.floor(p.y / TILE);
104:   const y1 = Math.floor((p.y + p.h - 0.01) / TILE);
105:   let hit = false;
106:   for (let tx = x0; tx <= x1; tx++) {
107:     for (let ty = y0; ty <= y1; ty++) {
108:       if (!isSolid(level, tx, ty, phase, dynamic)) continue;
109:       const top = ty * TILE, bottom = top + TILE;
110:       if (p.vy > 0) { p.y = top - p.h - 0.01; p.grounded = true; }
111:       else if (p.vy < 0) { p.y = bottom + 0.01; }
112:       else { p.y = top - p.h - 0.01; p.grounded = true; }
113:       p.vy = 0;
114:       hit = true;
115:     }
116:     if (hit) break;
117:   }
118: }
