120: function spikeBox(ch, tx, ty) {
121:   const t = TILE;
122:   switch (ch) {
123:     case '^': return { x: tx * t + 4, y: ty * t + t * 0.45, w: t - 8, h: t * 0.55 - 2 };
124:     case 'v': return { x: tx * t + 4, y: ty * t, w: t - 8, h: t * 0.55 - 2 };
125:     case '<': return { x: tx * t + t * 0.45, y: ty * t + 4, w: t * 0.55 - 2, h: t - 8 };
126:     case '>': return { x: tx * t, y: ty * t + 4, w: t * 0.55 - 2, h: t - 8 };
127:   }
128:   return null;
129: }
