131: export function touchingSpike(level, x, y, w, h) {
132:   const x0 = Math.floor((x + 3) / TILE), x1 = Math.floor((x + w - 3) / TILE);
133:   const y0 = Math.floor((y + 3) / TILE), y1 = Math.floor((y + h - 3) / TILE);
134:   for (let ty = y0; ty <= y1; ty++) {
135:     for (let tx = x0; tx <= x1; tx++) {
136:       const ch = tileAt(level, tx, ty);
137:       if (!isSpikeChar(ch)) continue;
138:       const b = spikeBox(ch, tx, ty);
139:       if (x < b.x + b.w && x + w > b.x && y < b.y + b.h && y + h > b.y) return true;
140:     }
141:   }
142:   return false;
143: }
