145: /**
146:  * Advance one fixed frame.
147:  * input: { left, right, jump, phasePressed, flipPressed }
148:  * opts: { dynamic(tx,ty,ch,phase) -> boolean|undefined, time }
149:  * returns events: { jumped, died, phaseBlocked, flipped, landed }
150:  */
151: export function stepPlayer(level, p, input, opts = {}) {
152:   const dynamic = opts.dynamic;
153:   const ev = { jumped: false, died: false, phaseBlocked: false, flipped: false, landed: false };
154: 
155:   if (!p.alive) return ev;
156: 
157:   // --- phase swap (refuse if it would embed the body) ---
158:   if (input.phasePressed) {
159:     const next = 1 - p.phase;
160:     if (!boxSolid(level, p.x, p.y, p.w, p.h, next, dynamic)) {
161:       p.phase = next;
162:       p.vy *= 0.35;
163:       ev.phaseSwapped = true;
164:     } else {
165:       ev.phaseBlocked = true;
166:     }
167:   }
168: 
169:   // --- gravity inversion (only with footing) ---
170:   if (input.flipPressed && (p.grounded || p.coyote > 0)) {
171:     p.gravDir *= -1;
172:     p.grounded = false;
173:     p.coyote = 0;
174:     p.vy = 0;
175:     ev.flipped = true;
176:   }
177: 
178:   const wasGrounded = p.grounded;
179:   p.grounded = false;
180: 
181:   // --- horizontal ---
182:   const dir = (input.right ? 1 : 0) - (input.left ? 1 : 0);
183:   if (dir !== 0) {
184:     p.vx += dir * K.accel;
185:     p.facing = dir;
186:   } else {
187:     p.vx *= wasGrounded ? K.frictionGround : K.frictionAir;
188:     if (Math.abs(p.vx) < 0.06) p.vx = 0;
189:   }
190:   if (p.vx > K.maxRun) p.vx = K.maxRun;
191:   if (p.vx < -K.maxRun) p.vx = -K.maxRun;
192: 
193:   // --- jump buffering / coyote ---
194:   if (input.jumpPressed) p.buffer = K.bufferFrames;
195:   if (wasGrounded) p.coyote = K.coyoteFrames;
196:   if (p.buffer > 0) p.buffer--;
197:   if (p.coyote > 0) p.coyote--;
198: 
199:   if (p.buffer > 0 && (p.coyote > 0 || wasGrounded)) {
200:     p.vy = -K.jump * p.gravDir;
201:     p.buffer = 0;
202:     p.coyote = 0;
203:     p.cut = false;
204:     ev.jumped = true;
205:   }
206: 
207:   // jump cut — releasing early trims the arc
208:   if (!input.jump && !p.cut && p.vy * p.gravDir < -2.2) {
209:     p.vy *= K.jumpCut;
210:     p.cut = true;
211:   }
212:   if (input.jump && p.vy * p.gravDir >= 0) p.cut = false;
213: 
214:   // --- gravity ---
215:   p.vy += K.gravity * p.gravDir;
216:   if (p.vy > K.maxFall) p.vy = K.maxFall;
217:   if (p.vy < -K.maxFall) p.vy = -K.maxFall;
218: 
219:   // --- integrate & collide, sub-stepped to stay safe at high speed ---
220:   const steps = Math.max(1, Math.ceil(Math.max(Math.abs(p.vx), Math.abs(p.vy)) / 6));
221:   for (let s = 0; s < steps; s++) {
222:     p.x += p.vx / steps;
223:     resolveX(level, p, p.phase, dynamic);
224:     p.y += p.vy / steps;
225:     resolveY(level, p, p.phase, dynamic);
226:   }
227: 
228:   if (!wasGrounded && p.grounded) ev.landed = true;
229: 
230:   if (p.grounded) p.coyote = K.coyoteFrames;
231: 
232:   if (touchingSpike(level, p.x, p.y, p.w, p.h)) {
233:     p.alive = false;
234:     ev.died = true;
235:   }
236: 
237:   // out of world (shouldn't happen in sealed frames, but free levels can fall)
238:   if (p.y > level.rows * TILE + 80 || p.y < -140) {
239:     p.alive = false;
240:     ev.died = true;
241:   }
242: 
243:   return ev;
244: }
